# ==============================================================================# 062_MODULE_REGISTRY.py# IOTEC MISSION CONTROL# MODULE REGISTRY# ==============================================================================from pathlib import Pathimport sqlite3import hashlibfrom datetime import datetimeDB = Path("mission_control.db")class ModuleRegistry:    def __init__(self):        self.conn = sqlite3.connect(DB, timeout=30)        self.conn.row_factory = sqlite3.Row        self.conn.execute("PRAGMA journal_mode=WAL")        self.conn.execute("PRAGMA busy_timeout=30000")        self.cur = self.conn.cursor()    # ------------------------------------------------------------------    def file_hash(self, file):        h = hashlib.sha256()        with open(file, "rb") as f:            while True:                chunk = f.read(65536)                if not chunk:                    break                h.update(chunk)        return h.hexdigest()    # ------------------------------------------------------------------    def category(self, filename):        name = filename.upper()        if "DATABASE" in name:            return "DATABASE"        if "EVENT" in name:            return "EVENT"        if "MISSION" in name:            return "MISSION"        if "ENGINE" in name:            return "ENGINE"        if "WATCH" in name:            return "WATCH"        if "REPORT" in name:            return "REPORT"        if "CORE" in name:            return "CORE"        return "GENERAL"    # ------------------------------------------------------------------    def register(self, file):        file = Path(file)        self.cur.execute("""        INSERT OR REPLACE INTO modules(            module_name,            category,            version,            enabled,            path,            created_at        )        VALUES(            ?,            ?,            ?,            1,            ?,            ?        )        """, (            file.name,            self.category(file.name),            self.file_hash(file),            str(file.resolve()),            datetime.now().isoformat()        ))    # ------------------------------------------------------------------    def scan(self, folder="."):        total = 0        for py in Path(folder).glob("*.py"):            try:                self.register(py)                total += 1            except Exception as e:                print("[ERRO]", py.name, e)        self.conn.commit()        return total    # ------------------------------------------------------------------    def total(self):        self.cur.execute("""        SELECT COUNT(*)        FROM modules        """)        return self.cur.fetchone()[0]    # ------------------------------------------------------------------    def list_modules(self):        self.cur.execute("""        SELECT            module_name,            category,            enabled        FROM modules        ORDER BY module_name        """)        return self.cur.fetchall()# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    registry = ModuleRegistry()    total = registry.scan()    print("=" * 70)    print("MODULE REGISTRY")    print("=" * 70)    print("Arquivos encontrados :", total)    print("Módulos registrados  :", registry.total())    print("=" * 70)    for module in registry.list_modules():        print(            module["module_name"],            "|",            module["category"]        )